def format_money(amount, currency):
    if currency not in PREFIX: raise ValueError(currency)
    a=_r(Decimal(str(amount)), ROUND_HALF_UP)
    s='-' if a<0 else ''
    return f"{s}{PREFIX[currency]}{abs(a)}"
'''
